Rules.InvariantScript:
UpdateContext(
    {
        locSelectedAccount: Self.Selected,
        locSelectedDeviceTypeInProject: Blank(),
        locSelectedOpexCost: Blank()
    }
);
UpdateContext(
    {
        locSelectedSubaccount: If(
            locSelectedAccount.Name = "Operation & Maintenance",
            LookUp(
                colOpexSubaccounts,
                Account.'Opex Account' = locSelectedAccount.'Opex Account'
            ),
            Blank()
        ),
        locSelectedSubaccountOandM: If(
            locSelectedAccount.Name = "Operation & Maintenance",
            true,
            false
        )
    }
);

With(
    {
        // Step 1: Get all first periods (cost types) for the current subaccount
        colFirstPeriods: Filter(
            colOpexProjectCosts,
            Subaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount' && IsBlank('Parent Cost')
        )
    },
    With(
        {
            colLastPeriods: ForAll(
                colFirstPeriods As FirstPeriod,
                With(
                    {
                        costTypePeriods: Filter(
                            colOpexProjectCosts,
                            Subaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount' && ('Parent Cost'.'Opex Project Cost' = FirstPeriod.'Opex Project Cost' || 'Opex Project Cost' = FirstPeriod.'Opex Project Cost')
                        )
                    },
                    // Last periods: where no other period references them as parent
                    Last(
                        Sort(
                            costTypePeriods,
                            'Start Date',
                            SortOrder.Ascending
                        )
                    )
                    /*
                    First(
                        Filter(
                            costTypePeriods,
                            CountRows(
                                Filter(
                                    costTypePeriods,
                                    'Parent Cost'.'Opex Project Cost' = 'Opex Project Cost'
                                )
                            ) = 0
                        )
                    )*/
                )
            )
        },
        With(
            {
                locTotal: CountRows(colLastPeriods),
                locCostAlignedDurationCount: CountRows(
                    Filter(
                        colLastPeriods As CostRow,
                        CostRow.'Align With Project Duration' = 'Align With Project Duration (Opex Project Costs)'.Yes
                    )
                ),
                locCostNotAlignedDurationCount: CountRows(
                    Filter(
                        colLastPeriods As CostRow,
                        CostRow.'Align With Project Duration' = 'Align With Project Duration (Opex Project Costs)'.No
                    )
                ),
                varCostsForDurationAligned: CountRows(
                    Filter(
                        colLastPeriods As CostRow,
                        CostRow.'Start Date' >= gblSelectedProject.'Project Start Date',
                        Text(
                            DateAdd(
                                DateAdd(
                                    CostRow.'Start Date',
                                    CostRow.'Opex Project duration years' * 12 + CostRow.'Opex Project duration months',
                                    TimeUnit.Months
                                ),
                                -1,
                                TimeUnit.Days
                //) < gblSelectedProject.'End Date',
                            )
                        ,"yyyy/mm/dd") = Text(gblSelectedProject.'End Date',"yyyy/mm/dd"),
                        CostRow.'Align With Project Duration' = 'Align With Project Duration (Opex Project Costs)'.Yes
                    )
                ),
                varCostsForNotDurationAligned: CountRows(
                    Filter(
                        colLastPeriods As CostRow,
                        CostRow.'Start Date' >= gblSelectedProject.'Project Start Date',
                        Text(
                            DateAdd(
                                DateAdd(
                                    CostRow.'Start Date',
                                    CostRow.'Opex Project duration years' * 12 + CostRow.'Opex Project duration months',
                                    TimeUnit.Months
                                ),
                                -1,
                                TimeUnit.Days
                //) < gblSelectedProject.'End Date',
                            )
                        ,"yyyy/mm/dd") = Text(gblSelectedProject.'End Date',"yyyy/mm/dd"),
                        CostRow.'Align With Project Duration' = 'Align With Project Duration (Opex Project Costs)'.No
                    )
                )
            },
            With(
                {
                    locCostsForNotDurationAligned: locCostNotAlignedDurationCount - varCostsForNotDurationAligned,
                    locCostsForDurationAligned: locCostAlignedDurationCount - varCostsForDurationAligned
                },
                If(
            // NEw Line
                    locTotal = 0,
                    Color.Transparent,
                    locCostAlignedDurationCount = 0 && locCostNotAlignedDurationCount = 0,
                    Color.Transparent,
                    locCostAlignedDurationCount > 0 && locCostsForDurationAligned = 0 && locCostNotAlignedDurationCount = 0,
                    ColorValue(gblAppTheme.palette.SuccessLight),
                    locCostAlignedDurationCount > 0 && locCostsForDurationAligned > 0 && locCostNotAlignedDurationCount = 0,
                    ColorFade(
                        ColorValue(gblAppTheme.palette.Warning),
                        60%
                    ),
                    locCostAlignedDurationCount = 0 && locCostNotAlignedDurationCount > 0 && locCostsForNotDurationAligned > 0,
                    Color.Transparent,
                    locCostAlignedDurationCount = 0 && locCostNotAlignedDurationCount > 0 && locCostsForNotDurationAligned = 0,
                    ColorValue(gblAppTheme.palette.SuccessLight),
                    locCostAlignedDurationCount > 0 && locCostsForDurationAligned = 0 && locCostNotAlignedDurationCount > 0 && locCostsForNotDurationAligned = 0,
                    ColorValue(gblAppTheme.palette.SuccessLight),
                    locCostAlignedDurationCount > 0 && locCostsForDurationAligned > 0,
                    ColorFade(
                        ColorValue(gblAppTheme.palette.Warning),
                        60%
                    ),
                    locCostAlignedDurationCount > 0 && locCostsForDurationAligned = 0 && locCostNotAlignedDurationCount > 0 && locCostsForNotDurationAligned > 0,
            //"Duration Match"--- This is changed from "" to "Duration Match" so that if not aligned period is out of range but we have aligned period in range, so it shows "Duration Match"       
//Color.Transparent
                    ColorValue(gblAppTheme.palette.SuccessLight)
                )
            )
        )
    )
)

With(
    {
        // Step 1: Get all first periods (cost types) for the current subaccount
        colFirstPeriods: Filter(
            colOpexProjectCosts,
            Subaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount' && IsBlank('Parent Cost')
        )
    },
    With(
        {
            colLastPeriods: ForAll(
                colFirstPeriods As FirstPeriod,
                With(
                    {
                        costTypePeriods: Filter(
                            colOpexProjectCosts,
                            Subaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount' && ('Parent Cost'.'Opex Project Cost' = FirstPeriod.'Opex Project Cost' || 'Opex Project Cost' = FirstPeriod.'Opex Project Cost')
                        )
                    },
                    // Last periods: where no other period references them as parent
                    Last(
                        Sort(
                            costTypePeriods,
                            'Start Date',
                            SortOrder.Ascending
                        )
                    )
                    /*
                    First(
                        Filter(
                            costTypePeriods,
                            CountRows(
                                Filter(
                                    costTypePeriods,
                                    'Parent Cost'.'Opex Project Cost' = 'Opex Project Cost'
                                )
                            ) = 0
                        )
                    )*/
                )
            )
        },
        With(
            {
                locTotal: CountRows(colLastPeriods),
                locCostAlignedDurationCount: CountRows(
                    Filter(
                        colLastPeriods As CostRow,
                        CostRow.'Align With Project Duration' = 'Align With Project Duration (Opex Project Costs)'.Yes
                    )
                ),
                locCostNotAlignedDurationCount: CountRows(
                    Filter(
                        colLastPeriods As CostRow,
                        CostRow.'Align With Project Duration' = 'Align With Project Duration (Opex Project Costs)'.No
                    )
                ),
                varCostsForDurationAligned: CountRows(
                    Filter(
                        colLastPeriods As CostRow,
                        CostRow.'Start Date' >= gblSelectedProject.'Project Start Date',
                        Text(
                        DateAdd(
                            DateAdd(
                                CostRow.'Start Date',
                                CostRow.'Opex Project duration years' * 12 + CostRow.'Opex Project duration months',
                                TimeUnit.Months
                            ),
                            -1,
                            TimeUnit.Days
                //) < gblSelectedProject.'End Date',
                        ),"yyyy/mm/dd") = Text(gblSelectedProject.'End Date',"yyyy/mm/dd"),
                        CostRow.'Align With Project Duration' = 'Align With Project Duration (Opex Project Costs)'.Yes
                    )
                ),
                varCostsForNotDurationAligned: CountRows(
                    Filter(
                        colLastPeriods As CostRow,
                        CostRow.'Start Date' >= gblSelectedProject.'Project Start Date',
                        Text(
                        DateAdd(
                            DateAdd(
                                CostRow.'Start Date',
                                CostRow.'Opex Project duration years' * 12 + CostRow.'Opex Project duration months',
                                TimeUnit.Months
                            ),
                            -1,
                            TimeUnit.Days
                //) < gblSelectedProject.'End Date',
                        ),"yyyy/mm/dd") = Text(gblSelectedProject.'End Date',"yyyy/mm/dd"),
                        CostRow.'Align With Project Duration' = 'Align With Project Duration (Opex Project Costs)'.No
                    )
                )
            },
            With(
                {
                    locCostsForNotDurationAligned: locCostNotAlignedDurationCount - varCostsForNotDurationAligned,
                    locCostsForDurationAligned: locCostAlignedDurationCount - varCostsForDurationAligned
                },
                If(
                    locTotal = 0,
                    "",
                    locCostAlignedDurationCount = 0 && locCostNotAlignedDurationCount = 0,
                    "",
                    locCostAlignedDurationCount > 0 && locCostsForDurationAligned = 0 && locCostNotAlignedDurationCount = 0,
                    "Duration Match",
                    locCostAlignedDurationCount > 0 && locCostsForDurationAligned > 0 && locCostNotAlignedDurationCount = 0,
                    "Duration Mismatch",
                    locCostAlignedDurationCount = 0 && locCostNotAlignedDurationCount > 0 && locCostsForNotDurationAligned > 0,
                    "",
                    locCostAlignedDurationCount = 0 && locCostNotAlignedDurationCount > 0 && locCostsForNotDurationAligned = 0,
                    "Duration Match",
                    locCostAlignedDurationCount > 0 && locCostsForDurationAligned = 0 && locCostNotAlignedDurationCount > 0 && locCostsForNotDurationAligned = 0,
                    "Duration Match",
                    locCostAlignedDurationCount > 0 && locCostsForDurationAligned > 0,
                    "Duration Mismatch",
                    locCostAlignedDurationCount > 0 && locCostsForDurationAligned = 0 && locCostNotAlignedDurationCount > 0 && locCostsForNotDurationAligned > 0,
                    "Duration Match"
                )
            )
        )
    )
)

Table(
    {
        ItemKey: "newOpexProjectCostType",
        ItemDisplayName: "Add Contract Type",
        ItemIconName: "Add",
        ItemEnabled: And(
            DataSourceInfo(
                'Opex Project Costs',
                DataSourceInfo.CreatePermission
            ),
            If(
                locSelectedSubaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount',
                IsBlank(locSelectedOpexCost),
                true
            ),
            IsBlank(
                LookUp(
                    'Opex Project Costs',
                    And(
                        Project.Project = gblSelectedProject.Project,
                        'Is Standard Contract?' = 'Is Standard Contract? (Opex Project Costs)'.Yes,
                        Subaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount'
                    )
                )
            )
        )
    },
    {
        ItemKey: "newOpexProjectCost",
        ItemDisplayName: "Add Period",
        ItemIconName: "Add",
        ItemEnabled: And(
            Not(IsBlank(locSelectedOpexCost)),
            locSelectedSubaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount',
            DataSourceInfo(
                'Opex Project Costs',
                DataSourceInfo.CreatePermission
            ),
            Not(locSelectedOpexCost.'Is Standard Contract?' = 'Is Standard Contract? (Opex Project Costs)'.Yes),
            Not(
                StartsWith(
                    locSelectedOpexCost.Name,
                    "Standard"
                )
            ),
            Not(
                CountRows(
                    Filter(
                        colOpexProjectCosts,
                        And(
                            Description = locCandidateOpexCostDesc,
                            DeviceTypeInProject.DeviceTypesInProject = locSelectedDeviceTypeInProject.DeviceTypesInProject
                        )
                    )
                ) > 0
            )
        )
    },
    {
        ItemKey: "newAddStandardContractKey",
        ItemDisplayName: "Add Standard Contract",
        ItemIconName: "Add",
        ItemEnabled: And(
            Not(
                IsBlank(
                    LookUp(
                        'OPEX & Land Lease Standard Assumptions',
                        And(
                            Country.Country = gblSelectedProject.Country.Country,
                            Technology = gblSelectedProject.Technology,
                            'Type Of Contract' = 'Contract Types'.'Opex Other',
                            'Opex Subaccount'.'Opex Subaccount' = ThisItem.'Opex Subaccount'
                        )
                    )
                )
            ),
            IsBlank(
                LookUp(
                    'Opex Project Costs',
                    And(
                        Project.Project = gblSelectedProject.Project,
                        'Is Standard Contract?' = 'Is Standard Contract? (Opex Project Costs)'.Yes,
                        Subaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount'
                    )
                )
            ),
            IsBlank(
                LookUp(
                    'Opex Project Costs',
                    And(
                        Project.Project = gblSelectedProject.Project,
                       // 'Is Standard Contract?' = 'Is Standard Contract? (Opex Project Costs)'.Yes,
                        Subaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount'
                    )
                )
            )
        )
    },
    {
        ItemKey: "editOpexProjectCost",
        ItemDisplayName: "Edit",
        ItemIconName: "Edit",
        ItemEnabled: And(
            Not(IsBlank(locSelectedOpexCost)),
            locSelectedSubaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount',
            RecordInfo(
                locSelectedOpexCost,
                RecordInfo.EditPermission
            ),
            Not(locSelectedOpexCost.'Is Standard Contract?' = 'Is Standard Contract? (Opex Project Costs)'.Yes),
            Not(
                StartsWith(
                    locSelectedOpexCost.Name,
                    "Standard"
                )
            )
        )
    },
    {
        ItemKey: "deleteOpexProjectCost",
        ItemDisplayName: "Delete",
        ItemIconName: "Delete",
        ItemEnabled: And(
            Not(IsBlank(locSelectedOpexCost)),
            locSelectedSubaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount',
            RecordInfo(
                locSelectedOpexCost,
                RecordInfo.DeletePermission
            ),
            If(
                StartsWith(
                    Lower(locSelectedOpexCost.Description),
                    "standard"
                ),
                IsBlank(locSelectedOpexCost.'Parent Cost'),
                Or(
                    IsBlank(locSelectedOpexCost.'Parent Cost'),
                    With(
                        {
                            locFirstPeriod: LookUp(
                                colOpexProjectCosts,
                                'Opex Project Cost' = locSelectedOpexCost.'Parent Cost'.'Opex Project Cost'
                            )
                        },
                        With(
                            {
                                locLastPeriod: Last(
                                    Sort(
                                        Filter(
                                            colOpexProjectCosts,
                                            'Parent Cost'.'Opex Project Cost' = locFirstPeriod.'Opex Project Cost'
                                        ),
                                        Name,
                                        SortOrder.Ascending
                                    )
                                )
                            },
                            locLastPeriod.'Opex Project Cost' = locSelectedOpexCost.'Opex Project Cost'
                        )
                    )
                )
            )
        )
    }
)

!IsEmpty(
    Filter(
        colOpexProjectCosts,
        Subaccount.'Opex Subaccount' = ThisItem.'Opex Subaccount'
    )
)
