If(
    locSelectedOpexCost.'Opex Project Cost' = ThisItem.'Opex Project Cost',
    UpdateContext(
        {
            locSelectedSubaccount: Blank(),
            locSelectedOpexCost: Blank(),
            locCandidateOpexCostDesc: Blank(),
            locSelectedOpexCostParent: Blank()
        }
    ),
    UpdateContext(
        {
            locSelectedSubaccount: gal_OpexCosts_Content_Subaccounts.Selected,
            locSelectedOpexCost: ThisItem,
            locCandidateOpexCostDesc: If(
                If(
                    IsBlank(locSelectedOpexCostParent),
                    false,
                    And(
                        IsMatch(
                            ThisItem.Description,
                            " - \d+",
                            MatchOptions.EndsWith
                        ),
                        locSelectedOpexCostParent.Description <> ThisItem.Description
                    )
                ),
                Left(
                    ThisItem.Description,
                    Find(
                        " - ",
                        ThisItem.Description
                    ) - 1
                ) & " - " & Value(
                    Mid(
                        Match(
                            ThisItem.Description,
                            " - \d+"
                        ).FullMatch,
                        4
                    )
                ) + 1,
                ThisItem.Description & " - 2"
            ),
            locSelectedOpexCostParent: LookUp(
                'Opex Project Costs',
                'Opex Project Cost' = ThisItem.'Parent Cost'.'Opex Project Cost'
            )
        }
    )
);

With(
    {
        locParentCost: Coalesce(
            ThisItem.'Parent Cost'.'Opex Project Cost',
            ThisItem.'Opex Project Cost'
        )
    },
    With(
        {
            locLastPeriod: Last(
                Sort(
                    Filter(
                        colOpexProjectCosts,
                        Subaccount.'Opex Subaccount' = ThisItem.Subaccount.'Opex Subaccount' && ('Parent Cost'.'Opex Project Cost' = locParentCost || 'Opex Project Cost' = locParentCost)
                    ),
                    Name,
                    SortOrder.Ascending
                )
            )
        },
        If(
            locLastPeriod.'Opex Project Cost' = ThisItem.'Opex Project Cost',
            And(
                ThisItem.'Start Date' < gblSelectedProject.'Project Start Date' || Not(
                    Text(
                    DateAdd(
                        DateAdd(
                            ThisItem.'Start Date',
                            ThisItem.'Opex Project duration years' * 12 + ThisItem.'Opex Project duration months',
                            TimeUnit.Months
                        ),
                        -1,
                        TimeUnit.Days
                    ),"yyyy/mm/dd") = Text( gblSelectedProject.'End Date',"yyyy/mm/dd")
                ),
                ThisItem.'Align With Project Duration' = 'Align With Project Duration (Opex Project Costs)'.Yes
            ),
            false
        )
    )
)

With(
    {
        varSvgImageRecord: LookUp(
            SVGImages,
            ImageName = If(
                ThisItem.'Opex Project Cost' = locSelectedOpexCost.'Opex Project Cost',
                "CircleDotBlue",
                "CircleEmpty"
            )
        )
    },
    With(
        {
            varImageData: Concatenate(
                "data:image/svg+xml;utf8, ",
                EncodeUrl(varSvgImageRecord.SVGCode)
            )
        },
        varImageData
    )
)

With(
    {
        varRecordPVModuleType: If(
            IsType(
                ThisItem.TypeInProject,
                PVModuleTypeInProjects
            ),
        //AsType(ThisItem.TypeInProject, PVModuleTypeInProjects).PVModule.Supplier,
            LookUp(
                PVModuleTypeInProjects,
                PVModuleTypeInProject = AsType(
                    ThisItem.TypeInProject,
                    PVModuleTypeInProjects
                ).PVModuleTypeInProject
            ),
            Blank()
        )
    },
    If(
        IsType(
            ThisItem.TypeInProject,
            PVModuleTypeInProjects
        ),
        If(
            Not(IsBlank(varRecordPVModuleType)),
            varRecordPVModuleType.Label
        ),
        IsType(
            ThisItem.TypeInProject,
            GeneratorTypeInProjects
        ),
        //AsType(ThisItem.TypeInProject, GeneratorTypeInProjects).Generator.'Turbine Type'
        LookUp(
            GeneratorTypeInProjects,
            GeneratorTypeInProject = AsType(
                ThisItem.TypeInProject,
                GeneratorTypeInProjects
            ).GeneratorTypeInProject
        ).Generator.'Turbine Type'
    )
)

