Rules.InvariantScript:
Table(
    {
        ItemKey: "newOpexProjectCost",
        ItemDisplayName: "Add Period",
        ItemIconName: "Add",
        ItemEnabled: And(
            DataSourceInfo(
                'Opex Project Costs',
                DataSourceInfo.CreatePermission
            ),
            Or(
                And(
                    IsBlank(locSelectedOpexCost),
                    CountIf(
                        colOpexProjectCosts,
                        DeviceTypeInProject.DeviceTypesInProject = ThisItem.DeviceTypesInProject
                    ) = 0
                ),
                And(
                    Not(IsBlank(locSelectedOpexCost)),
                    ThisItem.DeviceTypesInProject = locSelectedDeviceTypeInProject.DeviceTypesInProject,
                    With(
                        {
                            locFirstPeriod: LookUp(
                                colOpexProjectCosts,
                                Or(
                                    'Opex Project Cost' = locSelectedOpexCost.'Parent Cost'.'Opex Project Cost',
                                    And(
                                        IsBlank('Parent Cost'),
                                        'Opex Project Cost' = locSelectedOpexCost.'Opex Project Cost'
                                    )
                                )
                            )
                        },
                        With(
                            {
                                locLastPeriod: Last(
                                    Sort(
                                        Filter(
                                            colOpexProjectCosts,
                                            Or(
                                                'Parent Cost'.'Opex Project Cost' = locFirstPeriod.'Opex Project Cost',
                                                And(
                                                    IsBlank('Parent Cost'),
                                                    'Opex Project Cost' = locSelectedOpexCost.'Opex Project Cost'
                                                )
                                            )
                                        ),
                                        Name,
                                        SortOrder.Ascending
                                    )
                                )
                            },
                            locLastPeriod.'Opex Project Cost' = locSelectedOpexCost.'Opex Project Cost'
                        )
                    ),
                    Not(locSelectedOpexCost.'Is Standard Contract?' = 'Is Standard Contract? (Opex Project Costs)'.Yes)
                )
            )
        )
    },
    {
        ItemKey: "addStandardContract",
        ItemDisplayName: "Add Standard Contract",
        ItemIconName: "Add",
        ItemEnabled: And(
            !IsBlank(
                LookUp(
                    'OPEX & Land Lease Standard Assumptions',
                    And(
                        Country.Country = gblSelectedProject.Country.Country,
                        Technology = gblSelectedProject.Technology,
                        'Type Of Contract' = 'Contract Types'.'Opex O&M'
                    )
                )
            ),
            IsBlank(
                LookUp(
                    'Opex Project Costs',
                    And(
                        Project.Project = gblSelectedProject.Project,
                        'Is Standard Contract?' = 'Is Standard Contract? (Opex Project Costs)'.Yes,
                        DeviceTypeInProject.DeviceTypesInProject = ThisItem.DeviceTypesInProject
                    )
                )
            ),
            IsBlank(
                LookUp(
                    'Opex Project Costs',
                    And(
                        Project.Project = gblSelectedProject.Project,
                        DeviceTypeInProject.DeviceTypesInProject = ThisItem.DeviceTypesInProject
                    )
                )
            )
        )
    },
    {
        ItemKey: "editOpexProjectCost",
        ItemDisplayName: "Edit",
        ItemIconName: "Edit",
        ItemEnabled: And(
            locSelectedDeviceTypeInProject.TypeInProject = ThisItem.TypeInProject,
            Not(locSelectedOpexCost.'Is Standard Contract?' = 'Is Standard Contract? (Opex Project Costs)'.Yes),
            Not(
                StartsWith(
                    locSelectedOpexCost.Name,
                    "Standard"
                )
            )
        )
    },
    {
        ItemKey: "deleteOpexProjectCost",
        ItemDisplayName: "Delete",
        ItemIconName: "Delete",
        ItemEnabled: And(
            locSelectedDeviceTypeInProject.TypeInProject = ThisItem.TypeInProject,
            If(
                StartsWith(
                    Lower(locSelectedOpexCost.Description),
                    "standard"
                ),
                IsBlank(locSelectedOpexCost.'Parent Cost'),
                Or(
                    IsBlank(locSelectedOpexCost.'Parent Cost'),
                    With(
                        {
                            locFirstPeriod: LookUp(
                                colOpexProjectCosts,
                                'Opex Project Cost' = locSelectedOpexCost.'Parent Cost'.'Opex Project Cost'
                            )
                        },
                        With(
                            {
                                locLastPeriod: Last(
                                    Sort(
                                        Filter(
                                            colOpexProjectCosts,
                                            'Parent Cost'.'Opex Project Cost' = locFirstPeriod.'Opex Project Cost'
                                        ),
                                        Name,
                                        SortOrder.Ascending
                                    )
                                )
                            },
                            locLastPeriod.'Opex Project Cost' = locSelectedOpexCost.'Opex Project Cost'
                        )
                    )
                )
            )
        )
    }
)

